import base64

def extract(payload):
 c=(payload or {}).get('content')
 if isinstance(c,dict) and c.get('encoding')=='base64':
  return base64.b64decode(c.get('content','')).decode('utf-8','replace')
 if isinstance(c,list):
  return [x.get('name') for x in c if isinstance(x,dict) and x.get('name')]
 return None
